        runner.cpu.core.set_d(5, 0);
        assert!(!runner.try_exact_null_event_cycle_fastfwd(trap_pc, Some(100)));
        assert!(!runner.try_exact_null_event_cycle_fastfwd(trap_pc, Some(100)));
        for state in 1..=IDLE_CYCLE_MAX_PERIOD {
            runner.cpu.core.set_d(5, u32::from(state));
            assert!(!runner.try_exact_null_event_cycle_fastfwd(trap_pc, Some(100)));
        }
        runner.cpu.core.set_d(5, 0);
